import{PlatformBridge}from'../bridge.js';
import{currentLocale}from'../i18n.js';
const bridge=new PlatformBridge(),vi=()=>currentLocale()==='vi';
const size=bytes=>(bytes/1024**2).toFixed(1)+' MiB';
function node(tag,className,text){const item=document.createElement(tag);if(className)item.className=className;if(text!==undefined)item.textContent=text;return item;}
const panel=node('section','panel sync-panel web-storage'),heading=node('h2'),description=node('p','muted small'),status=node('p','small'),syncCache=node('p','small muted'),actions=node('div','detail-actions');status.setAttribute('role','status');syncCache.hidden=true;
const refresh=node('button','button button-secondary'),inspect=node('button','button button-secondary'),persist=node('button','button button-secondary'),install=node('button','button button-secondary'),update=node('button','button button-secondary'),downloads=node('div','web-downloads'),inventoryPanel=node('div','web-storage-inventory');downloads.dataset.webDownloads='';install.hidden=true;
for(const button of[refresh,inspect,persist,install,update])button.type='button';actions.append(refresh,inspect,persist,install,update);panel.append(heading,description,status,syncCache,actions,inventoryPanel,downloads);document.querySelector('#view-settings').append(panel);
const unused=node('button','button button-secondary'),unusedPanel=node('div','web-unused-assets');unused.type='button';actions.append(unused);panel.insertBefore(unusedPanel,downloads);
let current=null,prompt=null,registration=null,working=false,offline=null,inventory=null,inspecting=false,unusedPreview=null,unusedNotice=null;
function render(){
  heading.textContent=vi()?'Dữ liệu trình duyệt và cài đặt ứng dụng':'Browser storage and app installation';
  description.textContent=vi()?'Thư viện và tiến trình được lưu trong trình duyệt này. Trình duyệt hoặc người dùng có thể xóa dữ liệu của trang; hãy xuất bản lưu quan trọng ra tệp. Cài ứng dụng giúp mở nhanh và dùng tài nguyên đã lưu ngoại tuyến.':'Your library and progress are stored in this browser. Browser or site-data removal can clear them; export important saves to a file. Installing the app provides quick access and resources cached for offline use.';
  refresh.textContent=vi()?'Làm mới dung lượng':'Refresh storage';persist.textContent=vi()?'Yêu cầu giữ dữ liệu lâu dài':'Request persistent storage';install.textContent=vi()?'Cài OmniPlay':'Install OmniPlay';update.textContent=vi()?'Kiểm tra bản web mới':'Check for a web update';
  inspect.textContent=inspecting?(vi()?'Đang đọc dữ liệu đã lưu…':'Inspecting stored data…'):(vi()?'Xem chi tiết dữ liệu đã lưu':'Inspect stored data');inspect.disabled=inspecting;
  unused.textContent=vi()?'Tìm nội dung game không còn dùng':'Find unused game content';
  syncCache.hidden=!current?.sync_cache_error&&!(current?.sync_cache?.stored_bytes>0);syncCache.textContent=current?.sync_cache_error?(vi()?'Chưa đọc được dữ liệu đồng bộ đã mã hóa. Bản lưu cục bộ vẫn được giữ.':'Encrypted sync data could not be inspected. Local saved progress is retained.'):current?.sync_cache?`${vi()?'Dữ liệu đồng bộ đã mã hóa trên thiết bị':'Encrypted sync data on this device'}: ${(current.sync_cache.stored_bytes/1024**2).toFixed(1)} MiB · ${vi()?'Bản lưu đang chờ':'Waiting saves'}: ${current.sync_cache.inbox_count}`:'';
  if(current){const mib=bytes=>(bytes/1024**2).toFixed(1);status.textContent=`${vi()?'Game':'Games'}: ${mib(current.logical_assets_bytes)} MiB · ${vi()?'Tiến trình':'Saves'}: ${mib(current.logical_saves_bytes)} MiB · Firmware: ${mib(current.logical_firmware_bytes??0)} MiB · ${current.persistent?(vi()?'Đã được trình duyệt cho phép giữ dữ liệu':'Browser persistence granted'):(vi()?'Dữ liệu do trình duyệt quản lý':'Browser-managed storage')}${offline?` · ${offline.cores.filter(core=>core.cached).length}/${offline.cores.length} ${vi()?'core đã có bản ngoại tuyến':'cores cached offline'}`:''}`;}
  renderInventory();
  renderUnused();
}
function renderUnused(){
  unusedPanel.replaceChildren();if(unusedNotice)unusedPanel.append(node('p','small',`${vi()?'Đã xóa nội dung không còn dùng':'Unused content removed'}: ${unusedNotice.count} · ${size(unusedNotice.bytes)}`));
  const preview=unusedPreview;if(!preview)return;
  unusedPanel.append(node('h3','',vi()?'Nội dung game không còn trong thư viện':'Game content no longer used by the library'),node('p','small',`${preview.unused_assets} / ${preview.scanned_assets} · ${size(preview.unused_bytes)}`),node('p','muted small',vi()?'Chỉ xem một nhóm nội dung mỗi lượt. Game dùng chung nội dung vẫn được giữ; bản lưu, firmware và dữ liệu đồng bộ không bị xóa.':'Each inspection covers one batch. Content shared by library games is retained; saves, firmware and synchronization data are not deleted.'));
  const controls=node('div','detail-actions');
  const reload=node('button','button button-secondary',vi()?'Làm mới nhóm này':'Refresh this batch');reload.type='button';reload.addEventListener('click',()=>void task(reload,()=>loadUnused(preview.after_hash)));controls.append(reload);
  if(preview.unused_assets){const remove=node('button','button button-danger',vi()?'Xóa nhóm nội dung này':'Remove this content batch');remove.type='button';remove.addEventListener('click',()=>void task(remove,async()=>{const warning=vi()?`Xóa ${preview.unused_assets} nội dung game (${size(preview.unused_bytes)}) không còn được thư viện sử dụng? Bạn sẽ cần nhập lại tệp gốc để chơi các game đã gỡ.`:`Remove ${preview.unused_assets} unused game content objects (${size(preview.unused_bytes)})? You will need to import the original files to play removed games again.`;if(!confirm(warning))return;const result=await bridge.request('storage_unused_remove',{after_hash:preview.after_hash,revision:preview.revision},120000);unusedNotice={count:result.removed_assets,bytes:result.removed_blob_reference_bytes};inventory=null;unusedPreview=null;await load();if(result.more_available)await loadUnused(result.next_after);}));controls.append(remove);}
  if(preview.more_available){const next=node('button','button button-secondary',vi()?'Xem nhóm tiếp theo':'Inspect next batch');next.type='button';next.addEventListener('click',()=>void task(next,()=>loadUnused(preview.next_after)));controls.append(next);}
  const close=node('button','button button-secondary',vi()?'Đóng chi tiết':'Close details');close.type='button';close.addEventListener('click',()=>{if(working)return;unusedPreview=null;unusedNotice=null;renderUnused();});controls.append(close);unusedPanel.append(controls);
}
async function loadUnused(after){
  const value=await bridge.request('storage_unused_preview',{after_hash:after},120000);
  if(value?.schema_version!==1||typeof value.revision!=='string'||!/^[a-f0-9]{64}$/.test(value.revision)||![value.scanned_assets,value.unused_assets,value.unused_bytes].every(item=>Number.isSafeInteger(item)&&item>=0)||value.scanned_assets>64||value.unused_assets>value.scanned_assets||typeof value.more_available!=='boolean'||value.after_hash!==after||(value.next_after!==null&&!/^[a-f0-9]{64}$/.test(value.next_after)))throw new Error(vi()?'Chưa xác định được nội dung không còn dùng.':'Unused-content ownership could not be established.');
  unusedPreview=value;renderUnused();
}
function renderInventory(){
  inventoryPanel.replaceChildren();if(!inventory)return;
  const labels={assets:vi()?'Nội dung game':'Game content',saves:vi()?'Bản lưu tiến trình':'Saved progress',firmware_data:'Firmware',sync_slots:vi()?'Bản mã hóa chờ gửi':'Pending encrypted uploads',sync_parts:vi()?'Phần tải xuống đang giữ':'Retained download parts',sync_inbox:vi()?'Bản mã hóa chờ nhập':'Encrypted saves awaiting import'};
  inventoryPanel.append(node('h3','',vi()?'Nội dung nhị phân đã lưu':'Stored binary contents'));
  const list=node('dl','definition-list');
  for(const value of inventory.stores){const row=node('div');row.append(node('dt','',labels[value.store]),node('dd','',`${value.complete?'':(vi()?'Ít nhất ':'At least ')}${(value.blob_reference_bytes/1024**2).toFixed(1)} MiB · ${value.blob_count} ${vi()?'tệp':'objects'}`));list.append(row);}
  inventoryPanel.append(list);
  const at=new Date(inventory.sampled_at_ms);inventoryPanel.append(node('p','muted small',`${vi()?'Thời điểm đọc':'Sampled at'}: ${at.toLocaleString(currentLocale())}. ${vi()?'Dung lượng nội dung không bao gồm cache ứng dụng, chỉ mục và chi phí lưu trữ của trình duyệt; các bản sao có thể dùng chung dữ liệu trên đĩa.':'Content sizes exclude app caches, indexes and browser storage overhead; copies may share disk storage.'}`));
  if(current&&Number.isFinite(current.estimated_usage_bytes)&&Number.isFinite(current.estimated_quota_bytes))inventoryPanel.append(node('p','small',`${vi()?'Trình duyệt ước tính cho trang này':'Browser estimate for this origin'}: ${(current.estimated_usage_bytes/1024**2).toFixed(1)} / ${(current.estimated_quota_bytes/1024**2).toFixed(1)} MiB`));
  if(!inventory.complete)inventoryPanel.append(node('p','muted small',vi()?'Một phần dữ liệu vượt giới hạn đọc của lượt này. Các giá trị đó chỉ là mức tối thiểu, chưa thể xác nhận tổng dung lượng.':'Some data exceeded this inspection’s read limit. Those values are lower bounds; the full total is not established.'));
  const damaged=inventory.stores.reduce((total,value)=>total+value.missing_blobs+value.size_mismatches,0),mismatched=Object.values(inventory.accounting).some(value=>value.matches===false||value.declared===null);
  if(damaged||mismatched)inventoryPanel.append(node('p','small',vi()?'Kích thước hoặc thống kê của dữ liệu đã lưu không khớp. Hãy xuất các bản lưu quan trọng trước khi quản lý dữ liệu. Lượt đọc này không tự sửa hay xóa dữ liệu.':'Stored sizes or accounting do not match. Export important saves before managing data. This inspection does not repair or delete data.'));
  inventoryPanel.append(node('p','muted small',vi()?'Lượt đọc chỉ xem kích thước, chưa xác minh nội dung tệp hoặc quyết định tệp nào có thể xóa.':'This inspection reads sizes; it does not verify file contents or determine which files can be deleted.'));
}
async function task(button,action){if(working)return;working=true;button.disabled=true;try{await action();}catch(error){status.textContent=error.message;}finally{working=false;button.disabled=false;}}
async function load(){current=await bridge.request('storage_status');offline=await cacheStatus().catch(()=>null);render();}
function cacheStatus(){return new Promise((resolve,reject)=>{
  if(!navigator.serviceWorker?.controller){resolve(null);return;}const channel=new MessageChannel(),timer=setTimeout(()=>{channel.port1.close();reject(new Error('Offline status unavailable'));},5000);
  channel.port1.onmessage=event=>{clearTimeout(timer);channel.port1.close();const value=event.data;if(Array.isArray(value?.cores)&&value.cores.length<=32)resolve(value);else reject(new Error('Offline status unavailable'));};channel.port1.onmessageerror=()=>{clearTimeout(timer);channel.port1.close();reject(new Error('Offline status unavailable'));};navigator.serviceWorker.controller.postMessage({method:'cache_status'},[channel.port2]);
});}
refresh.addEventListener('click',()=>void task(refresh,load));persist.addEventListener('click',()=>void task(persist,async()=>{const answer=await bridge.request('storage_request_persistence');await load();if(!answer.granted)status.textContent=vi()?'Trình duyệt chưa cấp quyền giữ dữ liệu lâu dài. Bản lưu vẫn có thể được xuất ra tệp.':'The browser has not granted persistence. Saved progress can still be exported to a file.';}));
inspect.addEventListener('click',()=>void task(inspect,async()=>{inspecting=true;render();try{const value=await bridge.request('storage_inspect',{},120000);if(value?.schema_version!==1||value.scope!=='indexeddb_blob_references'||value.changes_made!==false||!Array.isArray(value.stores)||value.stores.length!==6||!value.accounting)throw new Error(vi()?'Chưa đọc được chi tiết dữ liệu.':'Stored-data inspection is unavailable.');inventory=value;}finally{inspecting=false;render();}}));
unused.addEventListener('click',()=>void task(unused,()=>loadUnused(null)));
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();prompt=event;install.hidden=false;});window.addEventListener('appinstalled',()=>{prompt=null;install.hidden=true;});
install.addEventListener('click',()=>void task(install,async()=>{if(!prompt)return;const offer=prompt;prompt=null;install.hidden=true;await offer.prompt();await offer.userChoice;}));
update.addEventListener('click',()=>void task(update,async()=>{if(!registration)throw new Error(vi()?'Trình duyệt chưa đăng ký được chế độ ngoại tuyến.':'Offline support is not registered in this browser.');await registration.update();status.textContent=registration.waiting?(vi()?'Bản web mới đã sẵn sàng. Lưu và đóng mọi cửa sổ OmniPlay, rồi mở lại để cập nhật.':'A web update is ready. Save and close every OmniPlay window, then reopen to update.'):(vi()?'Đã yêu cầu kiểm tra bản web mới.':'A web update check was requested.');}));
document.addEventListener('omniplay_locale_changed',render);render();await load().catch(error=>{status.textContent=error.message;});
if('serviceWorker'in navigator){
  try{registration=await navigator.serviceWorker.register(new URL('../service-worker.js',import.meta.url),{scope:new URL('../',import.meta.url).pathname,updateViaCache:'none'});registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)status.textContent=vi()?'Bản web mới sẽ áp dụng sau khi lưu và đóng các cửa sổ OmniPlay.':'The web update will apply after OmniPlay windows are saved and closed.';});});}
  catch{status.textContent=vi()?'Chế độ ngoại tuyến chưa được đăng ký. Thư viện vẫn dùng dữ liệu cục bộ của trình duyệt.':'Offline support was not registered. The library still uses local browser storage.';}
}
navigator.serviceWorker?.addEventListener('controllerchange',()=>void load().catch(()=>{}));
document.addEventListener('visibilitychange',()=>{if(document.hidden)void globalThis.omniplayLifecycle?.suspend().catch(()=>{});});
